def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_n(n):
    # Check n, n+1, ..., n+37
    for k in range(n, n + 38):
        s_k = sum_digits(k)
        if s_k % 11 == 0:
            return False  # Found a multiple of 11
    return True # All 38 sums are not multiples of 11

# Search up to 1,000,000
N_LIMIT = 1000000 
smallest_n = None

print("Starting extended search...")

for n in range(1, N_LIMIT + 1):
    if check_n(n):
        smallest_n = n
        print(f"Found candidate n: {n}")
        break

if smallest_n is None:
    print(f"No solution found up to N_LIMIT = {N_LIMIT}. Structural analysis needed.")

